488	    private static String getSpecifiedName(
489	            StructuralNode sn, boolean incParams, boolean dataDrivenNodesAsRegex) {
490	        String name = sn.getName();
491	        if (sn.isDataDriven() && dataDrivenNodesAsRegex) {
492	            // Non-greedy regex pattern
493	            return DATA_DRIVEN_NODE_REGEX;
494	        }
495	        int bracketIndex = name.lastIndexOf("(");
496	        if (bracketIndex >= 0) {
497	            // Strip the param summary off
498	            name = name.substring(0, bracketIndex);
499	        }
500	        int queryIndex = name.indexOf("?");
501	        if (queryIndex >= 0) {
502	            if (incParams) {
503	                // Escape the params
504	                String params = name.substring(queryIndex);
505	                name = name.substring(0, queryIndex) + regexEscape(params);
506	            } else {
507	                // Strip the parameters off
508	                name = name.substring(0, queryIndex);
509	            }
510	        }
511	
512	        try {
513	            if (sn.getURI().getPath() == null || sn.getURI().getPath().length() == 0) {
514	                // Its a top level node, return as is
515	                return name;
516	            }
517	        } catch (URIException e) {
518	            // Ignore
519	        }
520	
521	        int slashIndex = name.lastIndexOf('/');
522	        if (slashIndex >= 0) {
523	            name = name.substring(slashIndex + 1);
524	        }
525	        if (sn.isLeaf()) {
526	            int colonIndex = name.indexOf(":");
527	            if (colonIndex > 0) {
528	                // Strip the GET/POST/etc. off
529	                name = name.substring(colonIndex + 1);
530	            }
531	        }
532	        return name;
533	    }
