539	    public static String getRegexPattern(StructuralNode sn, boolean incChildren)
540	            throws DatabaseException {
541	        /*
542	         * The logic...
543	         * 	Loop up to parent / recurse up
544	         * 	for std nodes escape special cases
545	         * 	inc \/ between nodes
546	         * 	for NSPs use (.+?) ?
547	         */
548	
549	        StringBuilder sb = new StringBuilder();
550	        boolean incParams = sn.isLeaf() || !incChildren;
551	        boolean lastLeafReturned = false;
552	
553	        // Work back up the tree..
554	        while (!sn.isRoot()) {
555	            if (lastLeafReturned) {
556	                sb.insert(0, "/");
557	            }
558	            sb.insert(0, getRegexName(sn, incParams));
559	            sn = sn.getParent();
560	            incParams = false; // Only do this for the top node
561	            lastLeafReturned = true;
562	        }
563	        if (incChildren) {
564	            sb.append(".*");
565	        }
566	        return sb.toString();
567	    }
